/* @lc app=leetcode id=2049 lang=kotlin */
class Solution { fun countHighestScoreNodes(parents: IntArray): Int = parents.size.let { n -> Array(n) { mutableListOf<Int>() }.apply { parents.forEachIndexed { i, p -> if (p != -1) this[p].add(i) } }.let { adj -> LongArray(n).let { size -> DeepRecursiveFunction<Int, Long> { u -> (1L + adj[u].sumOf { callRecursive(it) }).also { size[u] = it } }.invoke(0).let { total -> (0 until n).map { u -> (adj[u].map { size[it] } + (total - size[u]).takeIf { it > 0 }).filterNotNull().let { if (it.isEmpty()) 1L else it.reduce { a, b -> a * b } } }.let { scores -> scores.maxOrNull()!!.let { maxS -> scores.count { it == maxS } } } } } } }